function solveNQueensImpl(n) {
  const result = [], cols = new Set(), d1 = new Set(), d2 = new Set();
  const queens = new Array(n);
  function bt(row) {
    if (row === n) {
      result.push(queens.map(c => '.'.repeat(c)+'Q'+'.'.repeat(n-c-1)));
      return;
    }
    for (let col = 0; col < n; col++) {
      if (cols.has(col)||d1.has(row-col)||d2.has(row+col)) continue;
      cols.add(col); d1.add(row-col); d2.add(row+col); queens[row]=col;
      bt(row+1);
      cols.delete(col); d1.delete(row-col); d2.delete(row+col);
    }
  }
  bt(0);
  return result;
}

function totalNQueensImpl(n) {
  let count = 0;
  const cols = new Set(), d1 = new Set(), d2 = new Set();
  function bt(row) {
    if (row === n) { count++; return; }
    for (let col = 0; col < n; col++) {
      if (cols.has(col)||d1.has(row-col)||d2.has(row+col)) continue;
      cols.add(col); d1.add(row-col); d2.add(row+col);
      bt(row+1);
      cols.delete(col); d1.delete(row-col); d2.delete(row+col);
    }
  }
  bt(0);
  return count;
}

