function existImpl(board, word) {
  const m=board.length, n=board[0].length;
  const DIRS=[[0,1],[0,-1],[1,0],[-1,0]];
  function dfs(r,c,idx){
    if(idx===word.length) return true;
    if(r<0||r>=m||c<0||c>=n) return false;
    if(board[r][c]!==word[idx]) return false;
    const tmp=board[r][c]; board[r][c]='#';
    for(const[dr,dc]of DIRS) if(dfs(r+dr,c+dc,idx+1)){board[r][c]=tmp;return true;}
    board[r][c]=tmp; return false;
  }
  for(let r=0;r<m;r++) for(let c=0;c<n;c++) if(dfs(r,c,0)) return true;
  return false;
}

function findWordsImpl(board, words) {
  const root={};
  for(const word of words){
    let node=root;
    for(const c of word){if(!node[c])node[c]={};node=node[c];}
    node['$']=word;
  }
  const m=board.length, n=board[0].length, result=[];
  const DIRS=[[0,1],[0,-1],[1,0],[-1,0]];
  function dfs(r,c,node){
    const char=board[r][c];
    if(!node[char]) return;
    const next=node[char];
    if(next['$']){result.push(next['$']);delete next['$'];}
    board[r][c]='#';
    for(const[dr,dc]of DIRS){
      const nr=r+dr,nc=c+dc;
      if(nr>=0&&nr<m&&nc>=0&&nc<n&&board[nr][nc]!=='#') dfs(nr,nc,next);
    }
    board[r][c]=char;
    if(Object.keys(next).length===0) delete node[char];
  }
  for(let r=0;r<m;r++) for(let c=0;c<n;c++) dfs(r,c,root);
  return result;
}

