function isValidImpl(s) {
  let open = 0;
  for (const c of s) {
    if (c === '(') open++;
    else if (c === ')') { open--; if (open < 0) return false; }
  }
  return open === 0;
}

function removeInvalidParenthesesImpl(s) {
  if (isValidImpl(s)) return [s];
  const result = [], visited = new Set([s]);
  let queue = [s], found = false;
  while (queue.length && !found) {
    const next = [];
    for (const curr of queue) {
      for (let i = 0; i < curr.length; i++) {
        if (curr[i] !== '(' && curr[i] !== ')') continue;
        const cand = curr.slice(0,i) + curr.slice(i+1);
        if (visited.has(cand)) continue;
        visited.add(cand);
        if (isValidImpl(cand)) { result.push(cand); found = true; }
        else if (!found) next.push(cand);
      }
    }
    queue = next;
  }
  return result;
}

