const PROBLEMS = {
  51: {constraint:'col+diagonal',state:'3 sets',returnType:'enumeration'},
  52: {constraint:'col+diagonal',state:'3 sets + count',returnType:'count'},
  37: {constraint:'row+col+box',state:'3 sets arrays',returnType:'search'},
  79: {constraint:'visited cell',state:'in-place #',returnType:'search'},
  212:{constraint:'word prefix',state:'Trie',returnType:'enumeration'},
  282:{constraint:'no leading zeros',state:'(total,last)',returnType:'enumeration'},
  301:{constraint:'valid parens',state:'BFS visited set',returnType:'enumeration'}
};

function classifyProblem(problemId) {
  return PROBLEMS[problemId] || null;
}

function isSearchProblem(problemId) {
  const p = PROBLEMS[problemId];
  return p ? p.returnType === 'search' : false;
}

function module5Summary() {
  const vals = Object.values(PROBLEMS);
  return {
    total: vals.length,
    searchProblems: vals.filter(p=>p.returnType==='search').length,
    enumerationProblems: vals.filter(p=>p.returnType!=='search').length
  };
}
